using System.ComponentModel;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpStdioServer;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool(Name = "fetch_data"), Description("Fetches JSON data from an external API endpoint.")]
    public static async Task<string> FetchDataAsync(
        IHttpClientFactory httpClientFactory,
        ILogger<ApiTools> logger,
        [Description("The API path to query (e.g. \"users/42\").")] string path,
        CancellationToken cancellationToken)
    {
        logger.LogInformation("Fetching data from path: {Path}", path);

        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path, cancellationToken);

        response.EnsureSuccessStatusCode();

        var body = await response.Content.ReadAsStringAsync(cancellationToken);
        logger.LogInformation("Received {Length} chars from {Path}", body.Length, path);

        return body;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpStdioServer;

[McpServerPromptType]
public sealed class SummarizationPrompts
{
    [McpServerPrompt(Name = "summarize"), Description("Generates a prompt asking the model to summarize the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional maximum number of sentences for the summary.")] int? maxSentences = 3)
    {
        var constraint = maxSentences.HasValue
            ? $" Limit the summary to at most {maxSentences} sentences."
            : string.Empty;

        return
        [
            new()
            {
                Role = Role.User,
                Content = new TextContentBlock($"Summarize the following text concisely.{constraint}\n\n{text}")
            }
        ];
    }
}

